<?php
namespace App\Services\Tax;
use App\Support\Database;use App\Support\TenantContext;use App\Support\Auth;
final class TaxCalculationService { public function calculate(int $profileId,int $taxYearId):array{$pdo=Database::pdo();$s=$pdo->prepare('SELECT COALESCE(SUM(gross_amount),0) FROM tax_income WHERE tenant_id=? AND tax_profile_id=? AND tax_year_id=?');$s->execute([TenantContext::id(),$profileId,$taxYearId]);$income=(float)$s->fetchColumn();$d=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM tax_deductions WHERE tenant_id=? AND tax_profile_id=? AND tax_year_id=?');$d->execute([TenantContext::id(),$profileId,$taxYearId]);$ded=(float)$d->fetchColumn();$taxable=max(0,$income-$ded);$result=['income'=>$income,'deductions'=>$ded,'taxable_income'=>$taxable,'note'=>'Tax rules are not hard-coded; configure jurisdiction-specific rules before production filing.'];$i=$pdo->prepare('INSERT INTO tax_calculations(tenant_id,tax_profile_id,tax_year_id,calculation_version,input_json,result_json,status,requires_review,created_by,created_at) VALUES(?,?,?,?,?,?,\'prepared\',1,?,NOW())');$i->execute([TenantContext::id(),$profileId,$taxYearId,'base-v1',json_encode(['income'=>$income,'deductions'=>$ded]),json_encode($result),Auth::id()]);return $result;}}
